from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Apartment":"Private dwelling unit inside a larger building; hallways/elevators may be shared while the home itself is private.","Bus Stop":"Designated place where buses pick up/drop off passengers; riders wait back from traffic and check route information.","Crosswalk":"Marked pedestrian crossing; users still look/listen and follow signals because paint does not physically stop vehicles.","Department Store":"Large retail store organized into multiple merchandise departments; it is a commercial place, not a public service office.","Elevator":"Lift transports people/goods vertically between floors; doors, capacity, and emergency controls require normal safety behavior.","Fire Station":"Base for firefighters, engines, rescue equipment, and training; emergency bays must stay clear.","Garage":"Building or bay stores/repairs vehicles; active repair areas can contain moving cars, tools, chemicals, and are not play spaces.","Hospital":"Healthcare facility provides diagnosis/treatment, emergency, inpatient, or specialist services; access and roles vary by department.","Information Sign":"Sign provides direction, rules, maps, or place names; wording/symbols must be read in context.","Junction":"Place where routes meet or split; road users follow signs, signals, markings, and right-of-way rules.","Kindergarten":"Early-childhood education setting focused on learning, play, routines, and social development; age structure varies by country.","Library":"Public/school institution lends or provides access to books, media, information, and study space; borrowing has return rules.","Market":"Place where multiple sellers offer food or goods; stall type and opening pattern vary widely.","Neighborhood":"Local area around homes, streets, services, and shared spaces; it has no single universal boundary shape.","Office":"Workplace for administrative, professional, or organizational tasks; some offices are public-facing and others private.","Police Car":"Marked or unmarked law-enforcement vehicle used for patrol/response; emergency operations belong to trained officers.","Queue":"Ordered line of people waiting for service; it organizes turns rather than being a place/building itself.","Restaurant":"Business prepares and serves meals/drinks; kitchen areas are staff work zones while dining areas serve customers.","School":"Education institution with classrooms, staff, shared facilities, and safety/arrival routines.","Taxi":"Passenger-for-hire road service; legal licensing, fares, and pickup rules vary by place.","University":"Higher-education institution supports teaching, research, and services across many buildings/departments.","Vet Clinic":"Veterinary clinic provides animal health examination/treatment; trained staff handle medical procedures and stressed animals.","Water Fountain":"Public drinking fountain supplies potable water when maintained for that purpose; it differs from decorative fountain.","X-ray Clinic":"Medical imaging clinic uses controlled X-ray equipment operated by trained professionals; patients follow positioning and radiation-safety instructions.","Yoga Studio":"Dedicated space for guided or independent yoga practice; instruction should suit age, ability, and health needs.","Zone Sign":"Sign marks a regulated or named area such as parking, speed, school, fare, or loading zone; exact rule comes from text/symbols.","Ambulance":"Emergency medical vehicle carries patients, clinicians, and equipment; sirens/lights do not give bystanders permission to follow closely.","Bakery":"Shop/workplace produces or sells breads/pastries; hot ovens and back-of-house equipment stay staff-only.","Exit Sign":"Sign identifies an exit or escape direction; in emergencies follow the actual route and staff instructions.","Fountain":"Decorative water feature circulates/sprays water; it is not automatically safe for drinking or wading.","Grocery Store":"Retail store sells food and household goods; refrigerated, shelf, and checkout areas organize products/flow.","Intersection":"Road junction where paths cross; signals/signs/markings coordinate conflicting movements.","Juice Shop":"Food/drink business prepares or sells juice; ingredients/allergens and hygiene matter more than the shop name.","Kiosk":"Small booth or stand provides tickets, information, food, or goods depending location.","Laundromat":"Self-service laundry facility contains washers/dryers; machines, detergents, hot surfaces, and doors require adult supervision.","Mailbox":"Receptacle for outgoing/incoming mail; access and collection rules depend on postal system.","Overpass":"Bridge carries one road/path above another, separating traffic levels.","Park":"Public green/recreation space can contain paths, play areas, fields, water, or habitat; posted rules vary.","Road":"Prepared route for vehicles and sometimes designated cycling/walking areas; pedestrians use sidewalks/crossings where provided.","Underground Train":"Rail transit operating through tunnels/underground sections; platforms and tracks remain controlled areas.","Van":"Enclosed road vehicle for passengers/cargo; exact use depends configuration.","X-crossing":"Project X-shaped crossing marker; users must follow the actual road/rail crossing signals rather than the X shape alone.","City Hall":"Municipal government building/offices support local administration and public services; access areas and procedures vary.","Doctor":"Medical professional diagnoses/treats health conditions; examination and treatment require consent, training, and clinical setting.","Hotel":"Lodging business provides guest rooms and services; guest/private/service areas have different access.","Newsstand":"Small retail stand sells newspapers, magazines, snacks, or small goods; inventory varies.","Quilt Shop":"Retail/craft shop sells quilts, fabric, thread, or sewing supplies; needles/cutters remain adult-managed.","Theater":"Venue presents plays, films, music, or performances; audience, stage, backstage, and technical areas have different access.","Walkway":"Designated pedestrian path separates or guides foot traffic; surface and crossing rules still matter.","Yard":"Outdoor area beside/around a building; private/public access depends ownership and use.","Zoo":"Facility houses animals for public viewing, education, conservation, and care; visitors keep barriers, no feeding/touching unless explicitly managed.","Subway":"Urban rapid-transit railway that may run underground, elevated, or at surface; platforms/tracks are controlled areas.",}
ACTIONS={"Crosswalk":"Trace stripes, then show stop-look cue.","Intersection":"Cross two fingers, then show stop/look.","Junction":"Make a Y with fingers; say follow signs/signals.","X-crossing":"Make an X, then show stop/look cue.","Police Car":"Point only; no siren imitation.","Ambulance":"Point only; no chasing/siren play.","X-ray Clinic":"Point only; trained professionals operate imaging equipment.","Laundromat":"Point; adult handles detergent and machine doors.","Fountain":"Point; say decorative water is not drinking water.","Zoo":"Point; keep barrier/no-feeding gesture.","Underground Train":"Point; draw a platform edge and stay back.","Subway":"Point; draw a platform edge and stay back."}
